    {"^([%d%.,]+) Silver\n([%d%.,]+) Silver$", "{1} Sølv\n{2} Sølv", " Silver\n"},
    {"^  %(Rang ([%d%.,]+)%)$", "  (Rang {1})", "  (Rang "},
    {"^  Obj%: ([%d%.,]+) entries$", "  Mål: {1} poster", " entries"},
    {"^([%d%.,]+) Copper$", "{1} Kobber", " Copper"},
    {"^%(Rang ([%d%.,]+)%)$", "(Rang {1})", "(Rang "},
    {"^%(Rank ([%d%.,]+)%)$", "(Rang {1})", "(Rank "},
    {"^([%d%.,]+) Mana$", "{1} Mana", " Mana"},
    {"^Mana ([%d%.,]+) %/ ([%d%.,]+)$", "Mana {1} / {2}", "Mana "},
    {"^Page ([%d%.,]+)$", "Side {1}", "Page "},
    {"^Side ([%d%.,]+)$", "Side {1}", "Side "},
}

local cache, cached = {}, 0

function ns.translateCaptured(text)
    local v = exact[text]
    if v then return v end
    local hit = cache[text]
    if hit ~= nil then return hit or nil end
    local result = false
    for i = 1, #list do
        local p = list[i]
        if text:find(p[3], 1, true) then
            local caps = { text:match(p[1]) }
            if caps[1] then
                result = (p[2]:gsub("{(%d+)}", function(k) return caps[tonumber(k)] or "" end))
                break
            end
        end
    end
    cached = cached + 1
    if cached > 3000 then cache, cached = {}, 1 end
    cache[text] = result
    return result or nil
end
